def invert_dict(d):
    inverted = {}
    for key, value in d.items():
        if value not in inverted:
            inverted[value] = []
        inverted[value].append(key)
    # Flatten single-element lists and sort multi-element ones
    result = {}
    for k, v in inverted.items():
        if len(v) == 1:
            result[k] = v[0]
        else:
            result[k] = sorted(v)
    return result

