import json

def merge_json_files(filepaths, output_path):
    merged = {}
    for filepath in filepaths:
        with open(filepath, 'r') as f:
            data = json.load(f)
            merged.update(data)
    with open(output_path, 'w') as f:
        json.dump(merged, f, indent=2)
    return merged

